lib/collection/src/grouping/group_by.rs L144-L179 (QueryGroupRequest::r#do — the code path that decides the no-payload-values disposition; NO field-existence validation, NO by-design annotation):

    async fn r#do(
        &self,
        collection: &Collection,
        read_consistency: Option<ReadConsistency>,
        shard_selection: ShardSelectorInternal,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<ScoredPoint>> {
        let mut request = self.source.clone();

        // Adjust limit to fetch enough points to fill groups
        request.limit = self.groups * self.group_size;
        request.prefetches.iter_mut().for_each(|prefetch| {
            increase_limit_for_group(prefetch, self.group_size);
        });

        let key_not_empty = Filter::new_must_not(Condition::IsEmpty(self.group_by.clone().into()));
        request.filter = Some(request.filter.unwrap_or_default().merge(&key_not_empty));

        let with_group_by_payload = Self::group_by_to_payload_selector(&self.group_by);

        // We're enriching the final results at the end, so we'll keep this minimal
        request.with_payload = with_group_by_payload;
        request.with_vector = WithVector::Bool(false);

        collection
            .query(
                request,
                read_consistency,
                shard_selection,
                timeout,
                hw_measurement_acc,
            )
            .await
    }

Companion evidence — lib/api/src/rest/schema.rs L1202-L1214: group_by carries only #[schemars(length(min = 1))] (doc-schema annotation, not a runtime validator) while sibling group_size carries #[validate(range(min = 1))] (the runtime check that produced the observed 422 on group_size=0). lib/collection/src/grouping/aggregator.rs L111-L118: 'assumes that the points always have the grouped_by field, else it just ignores them' with '// ignore points that don't have the group_by field' — a per-point skip mechanic; a whole-collection-absent field is filtered out earlier in r#do (L160-161) so zero points ever reach the aggregator and distill() returns [].
